import { isAddress, type Address } from "viem";
import generated from "../generated/deployments.json";
import { DEFAULT_PARAMS, type Params } from "./deviation";

/**
 * palmfi contract addresses. Source order: NEXT_PUBLIC_PALMFI_* env overrides, then deployments/arc.json
 * (synced into src/generated by scripts/sync-deployments.mjs). Missing addresses mean "not deployed yet".
 */
type Raw = Partial<Record<"hub" | "factory" | "orbitalHook" | "orbitalRouter", string>> & { blockNumber?: number; scoring?: Params };

const raw = generated as Raw;

function pick(envValue: string | undefined, fileValue: string | undefined): Address | undefined {
  const v = envValue || fileValue;
  return v && isAddress(v) && v !== "0x0000000000000000000000000000000000000000" ? (v as Address) : undefined;
}

export const deployments = {
  factory: pick(process.env.NEXT_PUBLIC_PALMFI_FACTORY, raw.factory),
  hub: pick(process.env.NEXT_PUBLIC_PALMFI_HUB, raw.hub),
  hook: pick(process.env.NEXT_PUBLIC_PALMFI_ORBITAL_HOOK, raw.orbitalHook),
  router: pick(process.env.NEXT_PUBLIC_PALMFI_ORBITAL_ROUTER, raw.orbitalRouter),
  /** Block the network was deployed at; log scans start here. */
  fromBlock: BigInt(process.env.NEXT_PUBLIC_PALMFI_FROM_BLOCK || raw.blockNumber || 0),
  /** The Sentinel's scoring params for this network (cre/sentinel/config.staging.json). */
  scoring: raw.scoring ?? DEFAULT_PARAMS,
};

export type Deployments = typeof deployments;

export function isDeployed(d: Deployments = deployments): d is Deployments & { factory: Address; hub: Address; hook: Address; router: Address } {
  return !!(d.factory && d.hub && d.hook && d.router);
}
